CREATE TABLE authority (item INTEGER, template INTEGER, crlExpire CHAR(15), crlNo INTEGER, crlDays INTEGER, dnPolicy VARCHAR(1024), FOREIGN KEY (item) REFERENCES items (id), FOREIGN KEY (template) REFERENCES items (id));
CREATE TABLE certs (item INTEGER, hash INTEGER, iss_hash INTEGER, serial VARCHAR(64), issuer INTEGER, ca INTEGER, cert TEXT, FOREIGN KEY (item) REFERENCES items (id), FOREIGN KEY (issuer) REFERENCES items (id));
CREATE TABLE crls (item INTEGER, hash INTEGER, num INTEGER, iss_hash INTEGER, issuer INTEGER, crl TEXT, FOREIGN KEY (item) REFERENCES items (id), FOREIGN KEY (issuer) REFERENCES items (id));
CREATE TABLE items(id INTEGER PRIMARY KEY, name VARCHAR(128), type INTEGER, source INTEGER, date CHAR(15), comment VARCHAR(2048), stamp INTEGER NOT NULL DEFAULT 0, del SMALLINT NOT NULL DEFAULT 0);
